public class ChangeSkinSponge implements PlatformPlugin<CommandSource> {

    private final Path dataFolder;
    private final Logger logger;
    private final Injector injector;
    private final PluginContainer container;

    private final ChangeSkinCore core = new ChangeSkinCore(this);
    private final SpongeSkinAPI api = new SpongeSkinAPI(this);

    //We will place more than one config there (i.e. H2/SQLite database) -> sharedRoot = false
    @Inject
    ChangeSkinSponge(Logger logger, @ConfigDir(sharedRoot = false) Path dataFolder, Injector injector, PluginContainer container) {
        this.dataFolder = dataFolder;
        this.logger = logger;
        this.injector = injector.createChildInjector(binder -> binder.bind(ChangeSkinCore.class).toInstance(core));
        this.container = container;
    }

    @Listener
    public void onConstruct(ConstructPluginEvent event) {
        //load config and database
        try {
            core.load(true);
        } catch (Exception ex) {
            logger.error("Error initializing plugin. Disabling...", ex);
        }
    }

    @Listener
    public void onRegisterCommand(RegisterCommandEvent<CommandManager.ParameterizedBuilder> event) {
        // Register LoginListener for events
        Sponge.eventManager().registerListeners(container, injector.getInstance(LoginListener.class));

        //command register
        event.register(container, injector.getInstance(SelectCommand.class).buildSpec(), "skin-select", "skinselect");
        event.register(container, injector.getInstance(InfoCommand.class).buildSpec(), "skin-info");
        event.register(container, injector.getInstance(UploadCommand.class).buildSpec(), "skin-upload");
        event.register(container, injector.getInstance(SetCommand.class).buildSpec(), "changeskin", "setskin", "skin");
        event.register(container, injector.getInstance(InvalidateCommand.class)
                .buildSpec(), "skininvalidate", "skin-invalidate");

        //incoming channel
        String updateChannelName = new NamespaceKey(ARTIFACT_ID, UPDATE_SKIN_CHANNEL).getCombinedName();
        String permissionChannelName = new NamespaceKey(ARTIFACT_ID, CHECK_PERM_CHANNEL).getCombinedName();
        RawDataChannel updateChannel = Sponge.game().channelManager().getOrCreate(this, updateChannelName);
        RawDataChannel permChannel = Sponge.game().channelManager().getOrCreate(this, permissionChannelName);
        updateChannel.play().listener(Type.SERVER, injector.getInstance(UpdateSkinListener.class));
        permChannel.play().listener(Type.SERVER, injector.getInstance(CheckPermissionListener.class));
    }

    @Listener
    public void onShutdown(StoppingEngineEvent<Server> event) {
        core.close();
    }

    public ChangeSkinCore getCore() {
        return core;
    }

    @Override
    public boolean hasSkinPermission(CommandSource invoker, UUID uuid, boolean sendMessage) {
        if (invoker.hasPermission(PomData.ARTIFACT_ID + ".skin.whitelist." + uuid)) {
            return true;
        }

        //disallow - not whitelisted or blacklisted
        if (sendMessage) {
            sendMessage(invoker, "no-permission");
        }

        return false;
    }

    public SpongeSkinAPI getApi() {
        return api;
    }

    @Override
    public String getName() {
        return PomData.NAME;
    }

    @Override
    public Path getPluginFolder() {
        return dataFolder;
    }

    @Override
    public Logger getLog() {
        return logger;
    }

    @Override
    public void sendMessage(CommandSource receiver, String key) {
        String message = core.getMessage(key);
        if (message != null && receiver != null) {
            receiver.sendMessage(LegacyComponentSerializer.legacySection().deserialize(message));
        }
    }
}

